function u(t){return t>=39?9:t>=37?8.5:t>=35?8:t>=33?7.5:t>=30?7:t>=27?6.5:t>=23?6:t>=20?5.5:t>=16?5:t>=13?4.5:t>=10?4:t>=8?3.5:t>=6?3:2.5}function f(t,e){if(t.type==="fill-blank")return e.trim().toLowerCase()===String(t.answer).trim().toLowerCase();if(t.type==="map-label")return e.trim().toUpperCase()===String(t.answer).trim().toUpperCase();if(t.type==="multi-select"&&Array.isArray(t.answer)){const n=new Set(e.split(",").filter(Boolean).map(r=>Number(r))),i=new Set(t.answer);return n.size===i.size&&[...i].every(r=>n.has(r))}return e===String(t.answer)}function s(t,e){if(t.type!=="multi-select"||!Array.isArray(t.answer))return f(t,e)?1:0;const n=new Set(e.split(",").filter(Boolean).map(a=>Number(a))),i=new Set(t.answer);let r=0;for(const a of n)i.has(a)&&r++;return r}function o(t){const e=Math.floor(t/60),n=t%60;return`${String(e).padStart(2,"0")}:${String(n).padStart(2,"0")}`}export{u as bandScore,o as formatCountdown,f as isCorrect,s as multiSelectScore};
